<script>
let disposalIndex=5;
function addDisposalRow(){const t=document.querySelector('#disposalRows tbody');const options=`@foreach($assets as $asset)<option value="{{ $asset->id }}" data-name="{{ $asset->asset_name }}" data-unit="{{ $asset->unit }}" data-qty="{{ $asset->quantity }}">{{ $asset->asset_name }}</option>@endforeach`;const tr=document.createElement('tr');tr.innerHTML=`<td><select name="items[${disposalIndex}][asset_id]" class="form-select form-select-sm disposal-asset"><option value="">— manual —</option>${options}</select><input name="items[${disposalIndex}][item_name]" class="form-control form-control-sm mt-1 disposal-name" placeholder="Nama" required></td><td><input type="number" name="items[${disposalIndex}][quantity]" class="form-control form-control-sm" min="1" value="1"></td><td><input name="items[${disposalIndex}][unit]" class="form-control form-control-sm" value="unit"></td><td><select name="items[${disposalIndex}][condition_code]" class="form-select form-select-sm"><option value="B">B</option><option value="RR">RR</option><option value="RB">RB</option></select></td><td><input name="items[${disposalIndex}][reason]" class="form-control form-control-sm" required></td><td><input name="items[${disposalIndex}][method]" class="form-control form-control-sm" required></td>`;t.appendChild(tr);disposalIndex++;}
document.addEventListener('change',function(e){if(!e.target.classList.contains('disposal-asset'))return;const row=e.target.closest('tr'),o=e.target.selectedOptions[0];if(o?.dataset.name){row.querySelector('.disposal-name').value=o.dataset.name;row.querySelector('.disposal-unit').value=o.dataset.unit||'unit';row.querySelector('.disposal-qty').value=o.dataset.qty||1;}});
</script>
